// Generated by tools/extract-hook.js from Frontend/src/modules/Food/pages/restaurant/PhoneNumbersPage.jsx (PhoneNumbersPage), then edited by hand
// where the web code touched the DOM. The logic is the web page's own.
/* eslint-disable react-hooks/exhaustive-deps, no-unused-vars, no-empty */
import { useState } from 'react'
import { useNavigate } from '../../../lib/webRouter'
import useRestaurantBackNavigation from '../useRestaurantBackNavigation'
import { Phone } from 'lucide-react-native'
import { document } from '../../../lib/webShim'



export function usePhoneNumbersPage() {
  const navigate = useNavigate()
  const goBack = useRestaurantBackNavigation()
  const [editingNumber, setEditingNumber] = useState(null) // { type: 'orderReminder1' | 'orderReminder2' | 'restaurantPage' }
  const [countryCode, setCountryCode] = useState("+91")
  const [phoneNumber, setPhoneNumber] = useState("")
  const [isCountryCodeOpen, setIsCountryCodeOpen] = useState(false)
  const [showOtpPopup, setShowOtpPopup] = useState(false)
  const [otp, setOtp] = useState(["", "", "", "", "", ""])
  const [pendingPhoneData, setPendingPhoneData] = useState(null) // Store phone data to save after OTP verification

  // Phone numbers data - only mobile now
  const [phoneData, setPhoneData] = useState({
    orderReminder1: "+91-9981127415",
    orderReminder2: "+91-9981127415",
    restaurantPage: "+91-9981127415"
  })

  // Country codes
  const countryCodes = [
    { code: "+91", country: "India", flag: "🇮🇳" },
    { code: "+1", country: "USA", flag: "🇺🇸" },
    { code: "+44", country: "UK", flag: "🇬🇧" },
    { code: "+971", country: "UAE", flag: "🇦🇪" },
    { code: "+65", country: "Singapore", flag: "🇸🇬" },
    { code: "+86", country: "China", flag: "🇨🇳" },
    { code: "+81", country: "Japan", flag: "🇯🇵" },
    { code: "+61", country: "Australia", flag: "🇦🇺" },
  ]

  const handleEditClick = (type) => {
    const currentNumber = phoneData[type]
    const parts = currentNumber.split('-')
    setCountryCode(parts[0] || "+91")
    setPhoneNumber(parts[1] || "")
    setEditingNumber(type)
  }

  const handleSaveEdit = () => {
    if (!editingNumber || !phoneNumber.trim()) return
    
    // Store the data to save after OTP verification
    setPendingPhoneData({
      type: editingNumber,
      value: `${countryCode}-${phoneNumber.trim()}`,
      countryCode: countryCode,
      phoneNumber: phoneNumber.trim()
    })
    
    // Close edit popup and show OTP popup
    setEditingNumber(null)
    setShowOtpPopup(true)
    setOtp(["", "", "", "", "", ""])
  }

  const handleCancelEdit = () => {
    setEditingNumber(null)
    setCountryCode("+91")
    setPhoneNumber("")
  }

  const handleOtpChange = (index, value) => {
    if (!/^\d*$/.test(value)) return // Only allow digits
    
    const newOtp = [...otp]
    newOtp[index] = value.slice(-1) // Only take last character
    
    // Auto-focus next input
    if (value && index < 5) {
      const nextInput = document.getElementById(`otp-${index + 1}`)
      if (nextInput) nextInput.focus()
    }
    
    setOtp(newOtp)
  }

  const handleOtpKeyDown = (index, e) => {
    if (e.key === "Backspace" && !otp[index] && index > 0) {
      const prevInput = document.getElementById(`otp-${index - 1}`)
      if (prevInput) prevInput.focus()
    }
  }

  const handleVerifyOtp = () => {
    const otpString = otp.join("")
    
    // For demo purposes, accept any 6-digit OTP
    // In production, this would verify against the backend
    if (otpString.length === 6) {
      // Save the phone number
      if (pendingPhoneData) {
        setPhoneData(prev => ({
          ...prev,
          [pendingPhoneData.type]: pendingPhoneData.value
        }))
      }
      
      // Close OTP popup and reset
      setShowOtpPopup(false)
      setPendingPhoneData(null)
      setOtp(["", "", "", "", "", ""])
      setCountryCode("+91")
      setPhoneNumber("")
    }
  }

  const handleResendOtp = () => {
    // Reset OTP input
    setOtp(["", "", "", "", "", ""])
    // In production, this would trigger a new OTP to be sent
  }

  const handleCancelOtp = () => {
    setShowOtpPopup(false)
    setPendingPhoneData(null)
    setOtp(["", "", "", "", "", ""])
  }

  const getDisplayNumber = (type) => {
    return phoneData[type] || ""
  }

  return {
    navigate,
    goBack,
    editingNumber,
    setEditingNumber,
    countryCode,
    setCountryCode,
    phoneNumber,
    setPhoneNumber,
    isCountryCodeOpen,
    setIsCountryCodeOpen,
    showOtpPopup,
    setShowOtpPopup,
    otp,
    setOtp,
    pendingPhoneData,
    setPendingPhoneData,
    phoneData,
    setPhoneData,
    countryCodes,
    handleEditClick,
    handleSaveEdit,
    handleCancelEdit,
    handleOtpChange,
    handleOtpKeyDown,
    handleVerifyOtp,
    handleResendOtp,
    handleCancelOtp,
    getDisplayNumber,
  }
}
